def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_pressure = 0.0
    rich_opp = 0
    desperate_opp = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                b = float(bid)
                prev_bids.append(b)
                opp_pressure = max(opp_pressure, b)

    if not alive_opponents:
        return float(min(budget, 18.0))

    slots = max(1, int(supply // WATER_REQ))
    scarcity = 1.0 if slots <= 1 else 0.0

    sorted_bids = sorted(prev_bids) if prev_bids else []
    if sorted_bids:
        top_prev = sorted_bids[-1]
        second_prev = sorted_bids[-2] if len(sorted_bids) >= 2 else sorted_bids[-1]
        avg_prev = sum(sorted_bids) / len(sorted_bids)
    else:
        top_prev = 0.0
        second_prev = 0.0
        avg_prev = 0.0

    urgency = 0
    if hp <= 2 or no_water_days >= 2:
        urgency = 3
    elif hp <= 4 or no_water_days >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    base = 0.0

    if urgency == 3:
        base = max(120.0, second_prev + 4.0, top_prev * 0.98)
        if scarcity > 0:
            base = max(base, top_prev + 2.5)
    elif urgency == 2:
        base = max(82.0, avg_prev * 0.78, second_prev + 1.5)
        if scarcity > 0:
            base = max(base, top_prev * 0.9)
    elif urgency == 1:
        if scarcity > 0:
            base = max(58.0, avg_prev * 0.55)
        else:
            base = 34.0
    else:
        if scarcity > 0:
            base = max(42.0, avg_prev * 0.4)
        else:
            base = 18.0

    if rich_opp >= 2 and urgency >= 1:
        base += 6.0
    if desperate_opp >= 2 and scarcity > 0:
        base += 8.0

    if day >= 8:
        base += 10.0 * urgency

    if hp >= 8 and no_water_days == 0 and scarcity == 0 and top_prev >= 120.0:
        base = min(base, 22.0)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 35.0
    elif day <= 9:
        reserve_floor = 15.0

    affordable = max(0.0, budget - reserve_floor)
    if urgency >= 2:
        affordable = budget

    bid = min(base, affordable if affordable > 0 else budget)

    if urgency == 0 and scarcity == 0 and top_prev >= 150.0:
        bid = min(bid, 15.0)

    if budget < 25.0:
        bid = budget

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

