def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Filter alive opponents
    alive_opps = [o for o in opponents_status.values() if o['alive']]

    # Baseline conservative bid
    base_bid = DAILY_SALARY * 0.55

    # If low HP, increase bid
    if hp <= 2:
        base_bid = DAILY_SALARY * 0.90
    elif hp <= 4:
        base_bid = DAILY_SALARY * 0.75

    # Check opponents' previous traces for aggression
    if alive_opps:
        prev_bids = []
        for opp in alive_opps:
            trace = opp.get('previous_trace')
            if trace and trace.get('bid') is not None:
                prev_bids.append(trace['bid'])
        if prev_bids:
            max_prev = max(prev_bids)
            # If opponents bid very high, undercut to save budget
            if max_prev > DAILY_SALARY * 0.85:
                if hp > 3:
                    base_bid = min(base_bid, DAILY_SALARY * 0.40)
                else:
                    base_bid = max(base_bid, DAILY_SALARY * 0.95)
            else:
                # Slightly above their max if needed
                target = max_prev + 1.5
                if target < base_bid:
                    base_bid = min(base_bid, target)
                else:
                    base_bid = max(base_bid, target)

    # Ensure we never bid more than budget
    final_bid = min(budget, base_bid)
    # Ensure non-negative
    if final_bid < 0:
        final_bid = 0
    return final_bid
